acity:0;pointer-events:none;transition:all 0.4s ease;z-index:999;}.tpw-back-top:hover{transform:translateY(-4px) scale(1.1);box-shadow:0 12px 36px rgba(43,131,235,0.5);}.tpw-back-top svg{width:24px;height:24px;}.tpw-faq{padding:40px 24px;}.tpw-faq-item{border:2px solid var(--card-border);border-radius:12px;margin-bottom:12px;overflow:hidden;background:var(--surface);transition:all 0.3s ease;box-shadow:0 2px 8px rgba(0,0,0,0.04);}.tpw-faq-q{width:100%;padding:20px 24px;text-align:left;font-size:1rem;font-weight:600;color:var(--text);display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:none;border:none;font-family:inherit;}.tpw-faq-q svg{width:20px;height:20px;flex-shrink:0;transition:transform 0.3s ease;color:var(--text-secondary);}.tpw-faq-a{max-height:0;overflow:hidden;transition:max-height 0.4s ease;}.tpw-faq-a-inner{padding:0 24px 20px;font-size:0.95rem;color:var(--text-secondary);line-height:1.7;}.tpw-cta{padding:60px 24px;}.tpw-cta-box{max-width:700px;margin:0 auto;text-align:center;padding:48px 32px;border-radius:20px;background:linear-gradient(135deg,#2B83EB 0%,#6366F1 100%);color:#fff;position:relative;overflow:hidden;box-shadow:0 10px 40px rgba(43,131,235,0.3);}.tpw-cta-box h2{font-size:2rem;font-weight:800;margin-bottom:12px;}.tpw-cta-box p{font-size:1.05rem;opacity:0.9;margin-bottom:28px;}.tpw-cta-form{display:flex;flex-direction:column;gap:14px;max-width:440px;margin:0 auto;}.tpw-cta-input{flex:1;padding:16px 24px;border-radius:50px;border:2px solid rgba(255,255,255,0.3);background:rgba(255,255,255,0.15);color:#fff;font-size:1rem;outline:none;font-family:inherit;backdrop-filter:blur(10px);}.tpw-cta-input:focus{border-color:rgba(255,255,255,0.6);background:rgba(255,255,255,0.25);}.tpw-cta-btn{padding:16px 32px;border-radius:50px;border:none;background:#fff;color:var(--brand);font-size:1rem;font-weight:700;cursor:pointer;white-space:nowrap;transition:all 0.4s ease;box-shadow:0 4px 16px rgba(0,0,0,0.2);}.tpw-cta-btn:hover{transform:scale(1.08);box-shadow:0 8px 28px rgba(0,0,0,0.3);}}@media (max-width:480px){.container{padding:0 16px;}.tpw-header-inner{padding:0 16px;}.tpw-logo span{max-width:none;white-space:nowrap;display:block;overflow:visible;text-overflow:unset;}.tpw-stats-grid{grid-template-columns:repeat(2,1fr);gap:10px;}.tpw-stat{padding:12px 6px;}.tpw-stat-num{font-size:1.6rem;color:#000;}.tpw-stat-label{font-size:0.68rem;color:#000;opacity:1;margin-top:0;}.tpw-hero{padding:16px 16px 32px;}.tpw-hero h1{font-size:clamp(1.6rem,7vw,2rem);line-height:1.4;}.tpw-hero p{font-size:0.82rem;}.tpw-hero-badge{font-size:0.7rem;padding:6px 12px;white-space:nowrap;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;}.tpw-hero-btns{flex-direction:column;}.tpw-hero-btns a{width:100%;justify-content:center;padding:12px;font-size:0.82rem;}.tpw-tools{padding:0 12px 40px;}.tpw-tool-card{font-size:0.78rem;padding:8px 6px;gap:6px;}.tpw-tool-badge{width:32px;height:32px;font-size:0.55rem;}.tpw-tool-grid{gap:4px;padding:8px;}.tpw-cat-item{width:72px;padding:10px 12px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:auto;}.tpw-cat-icon{width:40px;height:40px;margin:0 auto 6px;}.tpw-cat-icon svg{width:18px;height:18px;}.tpw-cat-name{font-size:0.62rem;font-weight:800;}.tpw-cat-scroll{justify-content:flex-start;padding:10px 16px;}.tpw-section-title{padding:32px 16px 20px;}.tpw-section-title h2{font-size:1.3rem;}.tpw-section-title p{font-size:0.85rem;line-height:1.5;max-width:440px;}.tpw-footer{padding:40px 20px 0;}.tpw-footer-col ul li a{font-size:0.85rem;padding:3px 0;}.tpw-back-top{width:48px;height:48px;bottom:20px;right:20px;}}@media (max-width:360px){.tpw-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr));}.tpw-logo span{max-width:none;font-size:0.9rem;white-space:nowrap;display:block;overflow:visible;text-overflow:unset;}.tpw-logo-icon{width:32px;height:32px;}.tpw-mobile-toggle{width:32px;height:32px;}.tpw-dark-toggle{width:46px;height:26px;}.tpw-hero h1{font-size:1.5rem;line-height:1.4;}.tpw-hero p{font-size:0.78rem;}.tpw-stat-num{font-size:1.5rem;color:#000;}.tpw-stat-label{font-size:0.62rem;color:#000;opacity:1;margin-top:0;}.tpw-cat-item{width:64px;padding:8px 10px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:auto;}.tpw-cat-icon{width:36px;height:36px;margin:0 auto 5px;}.tpw-cat-icon svg{width:16px;height:16px;}.tpw-cat-name{font-size:0.58rem;font-weight:800;}}.widget{margin:0;padding:0;}.widget-content{padding:0;margin:0;}.post-outer{margin:0;padding:0;background:none;border:none;}/* ===== SHARED TOOL PAGES (.tool-*) ===== */
.tool-hero{padding:44px 0 34px;margin:24px auto 0;max-width:2000px;text-align:center;background:linear-gradient(180deg,#BCD9F2 0%,#D0E4F7 40%,#E2EDF8 100%);position:relative;overflow:hidden;width:auto;border-radius:18px;}
[data-theme="dark"] .tool-hero{background:linear-gradient(180deg,#081422 0%,#0D1A30 40%,#0F1D33 100%);}
.tool-hero-inner{max-width:760px;margin:0 auto;padding:0 20px;position:relative;z-index:2;}
.tool-badge{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border:2px solid var(--card-border);border-radius:50px;padding:6px 16px;font-size:0.8rem;font-weight:600;color:var(--text-secondary);margin-bottom:16px;}
.tool-badge-dot{width:8px;height:8px;border-radius:50%;background:#22C55E;}
.tool-hero h1{font-size:clamp(1.6rem,4vw,2.4rem);font-weight:800;color:var(--text);letter-spacing:-0.03em;margin-bottom:12px;line-height:1.25;}
.tool-hero p{font-size:1rem;color:var(--text-secondary);max-width:600px;margin:0 auto;line-height:1.6;}
.tool-layout{display:grid;grid-template-columns:1fr 340px;gap:24px;align-items:start;padding:36px 0 20px;width:100%;}
.tool-main{min-width:0;}
.tool-sidebar{display:flex;flex-direction:column;gap:18px;min-width:0;}
.tool-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:24px;box-shadow:var(--shadow);}
.tool-card-header{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:2px solid var(--border);padding-bottom:14px;margin-bottom:16px;}
.tool-card-title{display:flex;align-items:center;gap:10px;font-size:0.95rem;font-weight:700;color:var(--text);}
.tool-card-title svg{width:18px;height:18px;color:var(--brand);}
.tool-card-actions{display:flex;align-items:center;gap:8px;}
.tool-card-btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:var(--radius-sm);background:var(--surface-2);border:1px solid var(--border);color:var(--text-secondary);font-size:0.82rem;font-weight:600;cursor:pointer;font-family:inherit;transition:all var(--transition);}
.tool-card-btn svg{width:14px;height:14px;}
.tool-card-btn:hover{border-color:var(--brand);color:var(--brand);}
.tool-textarea{width:100%;min-height:200px;padding:14px 16px;border:2px solid var(--border);border-radius:var(--radius);background:var(--bg);color:var(--text);font-family:inherit;font-size:0.95rem;line-height:1.6;resize:vertical;outline:none;transition:border-color .2s ease;box-sizing:border-box;}
.tool-textarea:focus{border-color:var(--brand);}
.stat-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:20px;box-shadow:var(--shadow);}
.stat-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);}
.stat-row:last-child{border-bottom:none;}
.stat-label{display:flex;align-items:center;gap:8px;font-size:0.85rem;font-weight:500;color:var(--text-secondary);}
.stat-label-icon{width:30px;height:30px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:0.7rem;font-weight:800;color:#fff;flex-shrink:0;}
.stat-label-icon.blue{background:#2B83EB;} .stat-label-icon.pink{background:#EC4899;} .stat-label-icon.green{background:#22C55E;} .stat-label-icon.purple{background:#6366F1;} .stat-label-icon.orange{background:#F97316;} .stat-label-icon.teal{background:#14B8A6;}
.stat-value{font-size:1.05rem;font-weight:700;color:var(--text);}
.privacy-card{background:rgba(43,131,235,0.07);border:1px solid rgba(43,131,235,0.2);border-radius:var(--radius);padding:18px;}
.privacy-card h3{font-size:0.92rem;font-weight:700;color:var(--text);margin-bottom:8px;display:flex;align-items:center;gap:8px;}
.privacy-card h3 svg{width:16px;height:16px;color:var(--brand);}
.privacy-card p{font-size:0.85rem;color:var(--text-secondary);line-height:1.6;margin:0;}
.features-section{padding:10px 0 50px;}
.features-title{text-align:center;font-size:clamp(1.2rem,2.5vw,1.6rem);font-weight:800;color:var(--text);letter-spacing:-0.02em;margin-bottom:6px;}
.features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:22px;}
.feature-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:26px 22px;text-align:center;transition:all .2s ease;}
.feature-card:hover{border-color:var(--brand);transform:translateY(-4px);box-shadow:var(--shadow-lg);}
.feature-icon{width:56px;height:56px;border-radius:14px;margin:0 auto 14px;display:flex;align-items:center;justify-content:center;font-size:1.5rem;color:#fff;}
.feature-icon.blue{background:#2B83EB;} .feature-icon.purple{background:#6366F1;} .feature-icon.green{background:#22C55E;} .feature-icon.orange{background:#F97316;} .feature-icon.pink{background:#EC4899;} .feature-icon.teal{background:#14B8A6;}
.feature-card h3{font-size:1rem;font-weight:700;margin-bottom:8px;color:var(--text);}
.feature-card p{font-size:0.88rem;color:var(--text-secondary);line-height:1.6;}
.form-group{margin-bottom:18px;}
.form-group label{display:block;font-weight:600;color:var(--text);margin-bottom:6px;font-size:0.95rem;}
.form-input,.form-select,.form-textarea{width:100%;padding:12px 14px;border:2px solid var(--border);border-radius:var(--radius);background:var(--bg);color:var(--text);font-family:inherit;font-size:0.95rem;outline:none;transition:border-color .2s ease;box-sizing:border-box;}
.form-input:focus,.form-select:focus,.form-textarea:focus{border-color:var(--brand);}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px;}
.btn-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:8px;}
.action-btn,.generate-btn,.copy-all-btn{display:inline-flex;align-items:center;gap:8px;background:var(--brand);color:#fff;font-weight:600;font-size:0.95rem;padding:12px 28px;border-radius:var(--radius);transition:transform .2s,box-shadow .2s;box-shadow:0 4px 14px rgba(43,131,235,0.35);border:none;cursor:pointer;font-family:inherit;}
.action-btn:hover,.generate-btn:hover,.copy-all-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(43,131,235,0.45);}
.clear-btn,.copy-btn,.download-btn,.alt-btn{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border:2px solid var(--border);color:var(--text);font-weight:600;font-size:0.9rem;padding:10px 20px;border-radius:var(--radius);transition:all var(--transition);cursor:pointer;font-family:inherit;}
.clear-btn:hover,.copy-btn:hover,.download-btn:hover,.alt-btn:hover{border-color:var(--brand);color:var(--brand);}
.tool-actions-bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;}
.output-area,.result-card{background:var(--bg);border:2px solid var(--border);border-radius:var(--radius);padding:16px;font-family:'Courier New',monospace;font-size:0.9rem;color:var(--text);overflow-wrap:break-word;word-break:break-word;min-height:60px;}
@media (max-width:1024px){
.tool-layout{grid-template-columns:1fr 300px;gap:18px;}
}
@media (max-width:768px){
.tool-layout{grid-template-columns:1fr;gap:16px;padding:24px 0 10px;}
.tool-sidebar{order:2;}
.features-grid{grid-template-columns:repeat(2,1fr);}
.tool-hero{padding:30px 0 26px;margin:16px 12px 0;}
.form-row{grid-template-columns:1fr;}
}
@media (max-width:480px){
.features-grid{grid-template-columns:1fr;}
.tool-card{padding:18px;}
.tool-card-header{flex-direction:column;align-items:flex-start;gap:10px;}
}
@media (max-width:360px){
.tool-hero{padding:24px 0 22px;margin:12px 8px 0;}
.tool-hero h1{font-size:1.5rem;}
}
/* ===== TOOL PAGES EXTENDED (shared across all tool pages) ===== */
/* ===== TOOL PAGES EXTENDED (shared across all tool pages) ===== */
:root{
  --brand-grad:linear-gradient(135deg,#2B83EB 0%,#6366F1 100%);
  --brand-grad-dark:linear-gradient(135deg,#1D6ED8 0%,#4F46E5 100%);
  --tool-radius:18px;
  --tool-radius-sm:12px;
  --tool-shadow:0 1px 3px rgba(15,23,42,.06),0 10px 30px rgba(15,23,42,.06);
  --tool-shadow-hover:0 6px 16px rgba(43,131,235,.12),0 18px 44px rgba(43,131,235,.16);
}
.tool-crumbs-wrap{padding:22px 0 2px;background:transparent;}
.tool-crumbs{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 12px;align-items:center;font-size:0.92rem;font-weight:500;}
.tool-crumbs a{color:var(--brand);font-weight:600;text-decoration:none;transition:color .2s,opacity .2s;}
.tool-crumbs a:hover{text-decoration:underline;color:var(--brand-dark);}
.tool-crumbs .crumb-cat{color:var(--brand);font-weight:700;background:rgba(43,131,235,.1);padding:5px 14px;border-radius:20px;transition:all .2s;border:1px solid rgba(43,131,235,.16);}
.tool-crumbs .crumb-cat:hover{background:rgba(43,131,235,.18);text-decoration:none;transform:translateY(-1px);}
.tool-crumbs span:not(.crumb-sep){color:var(--text-secondary);font-weight:600;}
.tool-crumbs .crumb-sep{color:var(--text-secondary);opacity:.45;font-size:0.85rem;}
.tool-hero{padding:42px 0 30px;margin:22px auto 0;max-width:2000px;text-align:center;background:radial-gradient(1100px 380px at 50% -12%,rgba(43,131,235,.10),transparent 62%),linear-gradient(180deg,#EEF4FB 0%,#E6EFFA 45%,#E2EDF8 100%);position:relative;overflow:hidden;width:auto;border-radius:22px;border:1px solid rgba(43,131,235,.12);box-shadow:0 12px 44px rgba(43,131,235,.10);}
[data-theme="dark"] .tool-hero{background:radial-gradient(1100px 380px at 50% -12%,rgba(99,102,241,.18),transparent 62%),linear-gradient(180deg,#0B1224 0%,#0E1830 45%,#0F1D33 100%);border-color:rgba(99,102,241,.18);box-shadow:0 12px 44px rgba(0,0,0,.35);}
.tool-hero-inner{max-width:760px;margin:0 auto;padding:0 20px;position:relative;z-index:2;}
.tool-hero-icon{width:68px;height:68px;border-radius:18px;background:var(--brand-grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.7rem;font-weight:700;flex-shrink:0;box-shadow:0 8px 22px rgba(43,131,235,.4);}
.tool-hero-inner:has(.tool-hero-icon){display:flex;align-items:center;justify-content:center;gap:22px;text-align:left;max-width:820px;}
.tool-hero-inner:has(.tool-hero-icon)>div:last-child{flex:1;min-width:0;text-align:left;}
.tool-hero-inner:has(.tool-hero-icon) h1{text-align:left;}
.tool-hero-inner:has(.tool-hero-icon) p{margin:0;text-align:left;}
.tool-hero h1{font-size:clamp(1.7rem,4vw,2.5rem);font-weight:800;color:var(--text);letter-spacing:-.03em;margin-bottom:10px;line-height:1.2;}
.tool-hero p{font-size:1.02rem;color:var(--text-secondary);max-width:600px;margin:0 auto;line-height:1.65;}
.tool-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(43,131,235,.08);border:1px solid rgba(43,131,235,.16);border-radius:50px;padding:7px 16px;font-size:0.8rem;font-weight:600;color:var(--text-secondary);margin-bottom:16px;}
.tool-badge-dot{width:8px;height:8px;border-radius:50%;background:#22C55E;box-shadow:0 0 0 3px rgba(34,197,94,.2);}
.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:28px;align-items:start;padding:32px 0 20px;width:100%;max-width:1280px;margin:0 auto;}
.tool-main{min-width:0;}
.tool-sidebar{display:flex;flex-direction:column;gap:20px;min-width:0;position:sticky;top:88px;}
.tool-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--tool-radius);padding:26px;box-shadow:var(--tool-shadow);transition:box-shadow .3s,transform .3s,border-color .3s;}
.tool-card:hover{box-shadow:var(--tool-shadow-hover);}
.tool-card-header{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid var(--border);padding-bottom:16px;margin-bottom:20px;}
.tool-card-title{display:flex;align-items:center;gap:12px;font-size:1.05rem;font-weight:700;color:var(--text);}
.tool-card-title svg{width:20px;height:20px;color:var(--brand);flex-shrink:0;}
.tool-card-actions{display:flex;align-items:center;gap:10px;}
.tool-card-btn{display:inline-flex;align-items:center;gap:7px;padding:9px 15px;border-radius:var(--tool-radius-sm);background:var(--surface-2);border:1px solid var(--border);color:var(--text-secondary);font-size:0.82rem;font-weight:600;cursor:pointer;font-family:inherit;transition:all .2s;}
.tool-card-btn svg{width:15px;height:15px;}
.tool-card-btn:hover{border-color:var(--brand);color:var(--brand);background:rgba(43,131,235,.06);}
.tool-textarea{width:100%;min-height:200px;padding:16px 18px;border:1.5px solid var(--border);border-radius:var(--tool-radius-sm);background:var(--surface-2);color:var(--text);font-family:inherit;font-size:0.95rem;line-height:1.6;resize:vertical;outline:none;transition:border-color .2s,box-shadow .2s;box-sizing:border-box;}
.tool-textarea:focus{border-color:var(--brand);box-shadow:0 0 0 4px rgba(43,131,235,.14);}
.stat-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--tool-radius);padding:22px;box-shadow:var(--tool-shadow);}
.stat-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--border);}
.stat-row:last-child{border-bottom:none;}
.stat-label{display:flex;align-items:center;gap:10px;font-size:0.88rem;font-weight:500;color:var(--text-secondary);}
.stat-label-icon{width:32px;height:32px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;font-size:0.7rem;font-weight:800;color:#fff;flex-shrink:0;}
.stat-label-icon.blue{background:#2B83EB;} .stat-label-icon.pink{background:#EC4899;} .stat-label-icon.green{background:#22C55E;} .stat-label-icon.purple{background:#6366F1;} .stat-label-icon.orange{background:#F97316;} .stat-label-icon.teal{background:#14B8A6;}
.stat-value{font-size:1.1rem;font-weight:700;color:var(--text);}
.privacy-card{background:linear-gradient(135deg,rgba(43,131,235,.08),rgba(99,102,241,.06));border:1px solid rgba(43,131,235,.18);border-radius:var(--tool-radius);padding:20px;}
.privacy-card h3{font-size:0.95rem;font-weight:700;color:var(--text);margin-bottom:8px;display:flex;align-items:center;gap:8px;}
.privacy-card h3 svg{width:17px;height:17px;color:var(--brand);}
.privacy-card p{font-size:0.85rem;color:var(--text-secondary);line-height:1.6;margin:0;}
.features-section{padding:14px 0 50px;max-width:1100px;margin:0 auto;}
.features-title{text-align:center;font-size:clamp(1.3rem,2.5vw,1.7rem);font-weight:800;color:var(--text);letter-spacing:-.02em;margin-bottom:6px;}
.features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:24px;}
.feature-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--tool-radius);padding:28px 24px;text-align:center;transition:all .25s ease;box-shadow:var(--tool-shadow);}
.feature-card:hover{border-color:var(--brand);transform:translateY(-5px);box-shadow:var(--tool-shadow-hover);}
.feature-icon{width:58px;height:58px;border-radius:16px;margin:0 auto 16px;display:flex;align-items:center;justify-content:center;font-size:1.6rem;color:#fff;box-shadow:0 8px 18px rgba(43,131,235,.25);}
.feature-icon.blue{background:#2B83EB;} .feature-icon.purple{background:#6366F1;} .feature-icon.green{background:#22C55E;} .feature-icon.orange{background:#F97316;} .feature-icon.pink{background:#EC4899;} .feature-icon.teal{background:#14B8A6;}
.feature-card h3{font-size:1.02rem;font-weight:700;margin-bottom:8px;color:var(--text);}
.feature-card p{font-size:0.88rem;color:var(--text-secondary);line-height:1.6;}
.form-group{margin-bottom:18px;}
.form-label,.form-group label{display:block;font-weight:600;color:var(--text);margin-bottom:7px;font-size:0.95rem;}
.form-input,.form-select,.form-textarea{width:100%;padding:13px 15px;border:1.5px solid var(--border);border-radius:var(--tool-radius-sm);background:var(--surface-2);color:var(--text);font-family:inherit;font-size:0.95rem;outline:none;transition:border-color .2s,box-shadow .2s;box-sizing:border-box;}
.form-input:focus,.form-select:focus,.form-textarea:focus{border-color:var(--brand);box-shadow:0 0 0 4px rgba(43,131,235,.14);}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px;}
.form-body{padding-top:4px;}
.form-left{margin-bottom:18px;}
.form-right{display:flex;flex-direction:column;gap:16px;}
.form-right .btn-row{margin-top:0;}
@media(min-width:769px){
.tool-main .form-body{display:grid;grid-template-columns:1fr 1fr;gap:0 24px;align-items:start;}
.tool-main .form-left{margin-bottom:0;}
.tool-main .form-right .btn-row{justify-content:flex-start;}
}
.btn-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:10px;}
.action-btn,.generate-btn,.copy-all-btn{display:inline-flex;align-items:center;gap:9px;background:var(--brand-grad);color:#fff;font-weight:700;font-size:0.98rem;padding:13px 30px;border-radius:var(--tool-radius-sm);transition:transform .2s,box-shadow .2s,filter .2s;border:none;cursor:pointer;font-family:inherit;box-shadow:0 6px 18px rgba(43,131,235,.4);}
.action-btn:hover,.generate-btn:hover,.copy-all-btn:hover{transform:translateY(-2px);box-shadow:0 10px 28px rgba(43,131,235,.5);filter:brightness(1.05);}
.action-btn:active,.generate-btn:active,.copy-all-btn:active{transform:translateY(0);}
.clear-btn,.copy-btn,.download-btn,.alt-btn{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border:1.5px solid var(--border);color:var(--text);font-weight:600;font-size:0.9rem;padding:11px 22px;border-radius:var(--tool-radius-sm);transition:all .2s;cursor:pointer;font-family:inherit;}
.clear-btn:hover,.copy-btn:hover,.download-btn:hover,.alt-btn:hover{border-color:var(--brand);color:var(--brand);background:rgba(43,131,235,.06);transform:translateY(-1px);}
.tool-actions-bar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;}
.output-area,.result-card,.result-box{background:var(--surface-2);border:1.5px solid var(--border);border-radius:var(--tool-radius-sm);padding:18px;font-family:'SFMono-Regular',Consolas,'Courier New',monospace;font-size:0.9rem;color:var(--text);overflow-wrap:break-word;word-break:break-word;min-height:60px;white-space:pre-wrap;}
@media(max-width:1024px){
.tool-layout{grid-template-columns:minmax(0,1fr) 300px;gap:22px;}
.features-grid{gap:18px;}
}
@media(max-width:768px){
.tool-layout{grid-template-columns:1fr;gap:18px;padding:24px 0 10px;}
.tool-sidebar{position:static;order:2;}
.features-grid{grid-template-columns:repeat(2,1fr);}
.tool-hero{padding:28px 16px 24px;margin:16px 14px 0;border-radius:18px;}
.tool-card{padding:20px;}
.form-row{grid-template-columns:1fr;}
.tool-hero-inner:has(.tool-hero-icon){flex-direction:column;text-align:center;}
.tool-hero-inner:has(.tool-hero-icon) h1,.tool-hero-inner:has(.tool-hero-icon) p{text-align:center;}
}
@media(max-width:480px){
.features-grid{grid-template-columns:1fr;}
.tool-card{padding:16px;border-radius:14px;}
.tool-card-header{flex-direction:column;align-items:flex-start;gap:10px;}
.tool-hero h1{font-size:1.5rem;}
.tool-crumbs{font-size:0.8rem;gap:4px 6px;}
.tool-crumbs .crumb-cat{padding:3px 9px;font-size:0.72rem;}
.action-btn,.generate-btn,.copy-all-btn{padding:12px 22px;font-size:0.92rem;}
.clear-btn,.copy-btn,.download-btn,.alt-btn{padding:10px 16px;font-size:0.85rem;}
}
@media(max-width:360px){
.tool-hero h1{font-size:1.35rem;}
.features-grid{grid-template-columns:1fr;}
}

/* ===== STATIC PAGES (about / contact / faq / legal) ===== */
.tool-hero:has(~ .about-content),.tool-hero:has(~ .contact-content),.tool-hero:has(~ .privacy-content),.tool-hero:has(~ .terms-content){max-width:900px;margin-left:auto;margin-right:auto;}
.privacy-section ul,.terms-section ul,.about-section ul{list-style:disc;padding-left:6px;}
.privacy-section a,.terms-section a,.about-section a{color:var(--brand);text-decoration:underline;}
.tool-hero:has(~ .about-content) p,.tool-hero:has(~ .contact-content) p,.tool-hero:has(~ .privacy-content) p,.tool-hero:has(~ .terms-content) p{max-width:100%;}


.about-content,.contact-content,.privacy-content,.terms-content{max-width:900px;margin:0 auto;padding:44px 20px 64px;}
.privacy-section,.terms-section,.about-section{margin-bottom:34px;}
.privacy-section h2,.terms-section h2,.about-section h2{font-size:1.4rem;font-weight:800;color:var(--text);margin-bottom:14px;letter-spacing:-0.02em;}
.privacy-section h3,.terms-section h3,.about-section h3{font-size:1.08rem;font-weight:700;color:var(--text);margin:22px 0 10px;}
.privacy-section p,.terms-section p,.about-section p{font-size:1rem;color:var(--text-secondary);line-height:1.8;margin-bottom:14px;}
.privacy-section ul,.terms-section ul,.about-section ul{margin:0 0 14px 22px;color:var(--text-secondary);line-height:1.8;}
.privacy-section li,.terms-section li,.about-section li{margin-bottom:6px;}
.why-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-top:18px;}
.why-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:24px;transition:all .2s ease;}
.why-card:hover{border-color:var(--brand);box-shadow:var(--shadow-md);}
.why-card-icon{font-size:1.6rem;margin-bottom:10px;}
.why-card h3{font-size:1.05rem;font-weight:700;margin-bottom:8px;color:var(--text);}
.why-card p{font-size:0.9rem;color:var(--text-secondary);line-height:1.6;}
.team-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:28px;line-height:1.8;color:var(--text-secondary);}
.info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:18px 0;}
.info-card{background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:22px;}
.info-card h3{font-size:1rem;font-weight:700;margin-bottom:6px;color:var(--text);}
.info-card p{font-size:0.88rem;color:var(--text-secondary);line-height:1.6;}
.contact-card{max-width:640px;margin:0 auto;background:var(--surface);border:2px solid var(--card-border);border-radius:var(--radius-lg);padding:34px;}
.form-group input,.form-group textarea{width:100%;padding:12px 14px;border:2px solid var(--border);border-radius:var(--radius);background:var(--bg);color:var(--text);font-family:inherit;font-size:0.95rem;outline:none;transition:border-color .2s ease;}
.form-group input:focus,.form-group textarea:focus{border-color:var(--brand);}
.form-success{display:none;background:rgba(34,197,94,0.12);border:1px solid #22C55E;color:#15803D;padding:12px 16px;border-radius:var(--radius);margin-bottom:18px;font-size:0.9rem;}
[data-theme="dark"] .form-success{color:#4ADE80;}
.submit-btn{display:inline-flex;align-items:center;gap:8px;background:var(--brand);color:#fff;font-weight:600;font-size:0.95rem;padding:12px 28px;border-radius:var(--radius);transition:transform .2s,box-shadow .2s;box-shadow:0 4px 14px rgba(43,131,235,0.35);border:none;cursor:pointer;font-family:inherit;}
.submit-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(43,131,235,0.45);}
.social-links{display:flex;gap:12px;justify-content:center;margin-top:26px;flex-wrap:wrap;}
.social-link{width:42px;height:42px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:1rem;transition:transform .2s,opacity .2s;text-decoration:none;}
.social-link:hover{transform:translateY(-3px);opacity:.9;}
.social-link:nth-child(1){background:#1DA1F2;} .social-link:nth-child(2){background:#4267B2;} .social-link:nth-child(3){background:#FF0000;} .social-link:nth-child(4){background:#94A3B8;}
.faq-section{max-width:900px;margin:0 auto;padding:44px 20px 64px;}
.faq-item{border:2px solid var(--card-border);border-radius:var(--radius);margin-bottom:10px;overflow:hidden;background:var(--surface);}
.faq-question{width:100%;padding:16px 20px;text-align:left;font-size:1rem;font-weight:600;color:var(--text);display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:none;border:none;font-family:inherit;}
.faq-question .faq-toggle{font-size:1.4rem;line-height:1;color:var(--brand);transition:transform .3s ease;}
.faq-item.open .faq-question .faq-toggle{transform:rotate(45deg);}
.faq-answer{max-height:0;overflow:hidden;transition:max-height .3s ease;}
.faq-item.open .faq-answer{max-height:600px;}
.faq-answer p{padding:0 20px 16px;font-size:0.92rem;color:var(--text-secondary);line-height:1.7;margin:0;}
@media (max-width:768px){
.info-grid{grid-template-columns:repeat(2,1fr);}
.why-grid{grid-template-columns:1fr;}
}
@media (max-width:480px){
.info-grid{grid-template-columns:1fr;}
}

body.script:
//
(function(){ var root=document.documentElement,s=localStorage.getItem('tpw-theme'); if(s)root.setAttribute('data-theme',s); else if(window.matchMedia&&window.matchMedia('(prefers-color-scheme:dark)').matches)root.setAttribute('data-theme','dark'); var dt=document.getElementById('tpwDarkToggle'); if(dt)dt.addEventListener('click',function(){var t=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',t);localStorage.setItem('tpw-theme',t);}); var mt=document.getElementById('tpwMobileToggle'),nav=document.getElementById('tpwNav'),mmenu=document.getElementById('tpwMobileMenu'); if(mt&&nav&&mmenu){nav.querySelectorAll('.tpw-nav-link').forEach(function(l){mmenu.appendChild(l.cloneNode(true));});mt.addEventListener('click',function(e){e.stopPropagation();mmenu.classList.toggle('tpw-menu-open');mt.classList.toggle('active');});mmenu.querySelectorAll('.tpw-nav-link').forEach(function(l){l.addEventListener('click',function(){mmenu.classList.remove('tpw-menu-open');mt.classList.remove('active');});});document.addEventListener('click',function(e){if(mmenu.classList.contains('tpw-menu-open')&&!mmenu.contains(e.target)&&e.target!==mt){mmenu.classList.remove('tpw-menu-open');mt.classList.remove('active');}});} var y=document.getElementById('tpwYear');if(y)y.textContent=new Date().getFullYear(); var cs=document.getElementById('tpwCatScroll');if(cs){var cp=document.getElementById('catPrev'),cn=document.getElementById('catNext');if(cp)cp.addEventListener('click',function(){cs.scrollBy({left:-320,behavior:'smooth'});});if(cn)cn.addEventListener('click',function(){cs.scrollBy({left:320,behavior:'smooth'});});} var si=document.getElementById('tpwHeaderSearchInput'); var sd=document.getElementById('tpwSearchDropdown'); var msi=document.getElementById('tpwMobileSearchInput'); var msd=document.getElementById('tpwMobileSearchDropdown'); var tools=[]; document.querySelectorAll('.tpw-tool-card').forEach(function(c){ var name=(c.querySelector('span')||{}).textContent||''; var href=c.getAttribute('href')||''; var cat=''; var p=c.closest('.tpw-tool-category'); if(p){var h=p.querySelector('h3');if(h)cat=h.textContent;} tools.push({name:name,href:href,cat:cat,el:c}); }); function buildResults(q){ if(!q)return[]; var ql=q.toLowerCase(),results=[]; for(var i=0;tools.length>i;i++){ if(tools[i].name.toLowerCase().indexOf(ql)!==-1||tools[i].cat.toLowerCase().indexOf(ql)!==-1)results.push(tools[i]); } return results; } function renderDropdown(dd,q){ if(!dd)return; dd.innerHTML=''; var results=buildResults(q); if(!q){dd.classList.remove('tpw-show');return;} if(!results.length){ var empty=document.createElement('div'); empty.className='tpw-search-empty'; empty.textContent='No tools found'; dd.appendChild(empty); dd.classList.add('tpw-show'); return; } var max=Math.min(results.length,8); for(var j=0;max>j;j++){ var t=results[j]; var item=document.createElement('div'); item.className='tpw-search-item'; item.setAttribute('data-href',t.href); var badge=t.el.querySelector('.tpw-tool-badge'); var bd=document.createElement('div'); bd.className=badge?badge.className:'tpw-tool-badge bg-blue'; if(badge){var bi=badge.querySelector('img'); if(bi){bd.appendChild(bi.cloneNode(true));} else {bd.textContent=badge.textContent;}} else {bd.textContent='';} var info=document.createElement('div'); info.className='tpw-search-item-info'; var nm=document.createElement('div'); nm.className='tpw-search-item-name'; nm.textContent=t.name; var ct=document.createElement('div'); ct.className='tpw-search-item-cat'; ct.textContent=t.cat; info.appendChild(nm); info.appendChild(ct); item.appendChild(bd); item.appendChild(info); dd.appendChild(item); (function(href){ function go(e){e.preventDefault();e.stopPropagation();window.location.href=href;} item.addEventListener('mousedown',go); item.addEventListener('touchstart',go,{passive:false}); })(t.href); } dd.classList.add('tpw-show'); } function bindSearch(input,dropdown){ if(!input||!dropdown)return; input.addEventListener('input',function(){renderDropdown(dropdown,input.value.trim());}); input.addEventListener('focus',function(){if(input.value.trim())renderDropdown(dropdown,input.value.trim());}); input.addEventListener('blur',function(){setTimeout(function(){dropdown.classList.remove('tpw-show');},300);}); input.addEventListener('keydown',function(e){ if(e.key==='Enter'){ e.preventDefault(); var active=dropdown.querySelector('.tpw-search-item.tpw-active'); if(active)window.location.href=active.getAttribute('data-href'); else if(input.value.trim())window.location.href='/search?q='+encodeURIComponent(input.value.trim()); } else if(e.key==='Escape'){dropdown.classList.remove('tpw-show');} }); } bindSearch(si,sd); bindSearch(msi,msd); var sbtn=document.getElementById('tpwSearchBtn'),msbar=document.getElementById('tpwMobileSearch'); if(sbtn&&msbar){sbtn.addEventListener('click',function(e){e.preventDefault(); e.stopPropagation(); var msw=document.getElementById('tpwMobileSearch').parentElement; if(msbar){msw.classList.toggle('tpw-search-open');msi.focus();}});}  var bt=document.getElementById('tpwBackTop'); if(bt){window.addEventListener('scroll',function(){if(window.scrollY>400)bt.classList.add('show');else bt.classList.remove('show');});bt.addEventListener('click',function(e){e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});});} var counters=document.querySelectorAll('.tpw-stat-num[data-target]'); var counterDone=false; function animateCounters(){ if(counterDone)return; if(!counters.length)return; var first=counters[0]; var rect=first.getBoundingClientRect(); if(rect.top>window.innerHeight||0>rect.bottom)return; counterDone=true; counters.forEach(function(el){ var target=parseInt(el.getAttribute('data-target'),10); var prefix=el.getAttribute('data-prefix')||''; var suffix=el.getAttribute('data-suffix')||''; var duration=2000; var start=performance.now(); function update(now){ var elapsed=now-start; var progress=Math.min(elapsed/duration,1); var eased=1-Math.pow(1-progress,3); var current=Math.round(eased*target); el.textContent=prefix+current+suffix; if(1>progress)requestAnimationFrame(update); } requestAnimationFrame(update); }); } window.addEventListener('scroll',animateCounters); animateCounters(); var catItems=document.querySelectorAll('.tpw-cat-item'); var toolCats=document.querySelectorAll('.tpw-tool-category'); var allToolsSection=document.querySelector('#tpw-tools'); function showAllTools(){toolCats.forEach(function(tc){tc.style.display='';});catItems.forEach(function(ci){ci.classList.remove('tpw-cat-active');});} var allToolsLink=document.querySelector('.tpw-nav-link[href="#tpw-tools"]'); if(allToolsLink){allToolsLink.addEventListener('click',function(e){e.preventDefault();showAllTools();if(allToolsSection){setTimeout(function(){window.scrollTo({top:allToolsSection.offsetTop-80,behavior:'smooth'});},100);}});} catItems.forEach(function(item){ item.addEventListener('click',function(e){ e.preventDefault(); if(this.classList.contains('tpw-cat-showall')){ showAllTools(); catItems.forEach(function(ci){ci.classList.remove('tpw-cat-active');}); this.classList.add('tpw-cat-active'); return; } var href=this.getAttribute('href'); var catId=href.replace('#',''); toolCats.forEach(function(tc){ if(tc.id===catId){tc.style.display='';} else{tc.style.display='none';} }); catItems.forEach(function(ci){ci.classList.remove('tpw-cat-active');}); this.classList.add('tpw-cat-active'); var targetCat=document.getElementById(catId); if(targetCat){window.scrollTo({top:targetCat.offsetTop-160,behavior:'smooth'});} }); }); })();
//
